import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
import { useLoaderData, useNavigate, useRevalidator } from "react-router";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";
import { getShopSubscription } from "../billing.server";
import { PLAN_LIMITS } from "../plans";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Banner,
  InlineGrid,
  Icon,
  ProgressBar,
  Box,
  Divider,
} from "@shopify/polaris";
import {
  PlusIcon,
  ExternalIcon,
  StatusActiveIcon,
  AlertCircleIcon,
} from "@shopify/polaris-icons";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const zipCodes = await db.zipCode.findMany({ where: { shop } });
  const [deliveryRulesCount, waitlistCount, subscription] = await Promise.all([
    db.deliveryRule.count({ where: { shop } }),
    db.waitlistEntry.count({ where: { shop } }),
    getShopSubscription(shop),
  ]);

  const stats = {
    total: zipCodes.length,
    allowed: zipCodes.filter((z) => z.type === "allowed").length,
    blocked: zipCodes.filter((z) => z.type === "blocked").length,
    deliveryRules: deliveryRulesCount,
    waitlist: waitlistCount,
  };

  // Detect whether the App Embed is enabled in the active theme
  let appEmbedEnabled = false;
  let activeThemeName: string | null = null;
  let themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
  let themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/current/editor?context=apps`;

  try {
    const themesRes = await fetch(
      `https://${shop}/admin/api/2026-01/themes.json?role=main`,
      { headers: { "X-Shopify-Access-Token": session.accessToken ?? "" } },
    );
    if (themesRes.ok) {
      const themesJson = (await themesRes.json()) as {
        themes?: { id: number; name: string }[];
      };
      const mainTheme = themesJson.themes?.[0];
      if (mainTheme) {
        const numericId = String(mainTheme.id);
        activeThemeName = mainTheme.name;
        themeEditorUrl = `https://${shop}/admin/themes/${numericId}/editor`;
        themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/${numericId}/editor?context=apps`;

        const assetRes = await fetch(
          `https://${shop}/admin/api/2026-01/themes/${numericId}/assets.json?asset%5Bkey%5D=config%2Fsettings_data.json`,
          { headers: { "X-Shopify-Access-Token": session.accessToken ?? "" } },
        );
        if (assetRes.ok) {
          const assetJson = (await assetRes.json()) as {
            asset?: { value?: string };
          };
          const content = assetJson?.asset?.value;
          if (content) {
            const settingsData = JSON.parse(content) as {
              current?: { blocks?: Record<string, unknown> };
            };
            const blocks = settingsData?.current?.blocks ?? {};
            appEmbedEnabled = Object.values(blocks).some((block) => {
              const b = block as { type?: string; disabled?: boolean };
              return (
                typeof b.type === "string" &&
                (b.type.includes("app-embed") || b.type.includes("app_embed")) &&
                b.disabled !== true
              );
            });
          }
        }
      }
    }
  } catch {
    // Non-fatal — embed status defaults to false
  }

  return {
    stats,
    subscription,
    appEmbedEnabled,
    activeThemeName,
    themeEditorUrl,
    themeEditorAppEmbedsUrl,
  };
};

export default function DashboardPage() {
  const {
    stats,
    subscription,
    appEmbedEnabled,
    activeThemeName,
    themeEditorUrl,
    themeEditorAppEmbedsUrl,
  } = useLoaderData<typeof loader>();
  const navigate = useNavigate();
  const { revalidate, state: revalidateState } = useRevalidator();
  const limits = PLAN_LIMITS[subscription.planTier];
  const isFreePlan = subscription.planTier === "free";
  const isEmpty = stats.total === 0;

  const usagePercent =
    limits.maxZipCodes !== Infinity
      ? Math.min(100, Math.round((stats.total / limits.maxZipCodes) * 100))
      : 0;

  const planLabel =
    subscription.planTier === "ultimate"
      ? "Ultimate"
      : subscription.planTier === "pro"
        ? "Pro"
        : "Free";

  return (
    <Page
      title="Dashboard"
      subtitle={`${planLabel} Plan`}
      primaryAction={{
        content: "Add Zip Code",
        icon: PlusIcon,
        onAction: () => navigate("/app/zip-codes"),
      }}
    >
      <Box paddingBlockEnd="1600">
        <BlockStack gap="500">

          {/* ─── 1. APP STATUS ─── */}
          {appEmbedEnabled ? (
            <Banner
              tone="success"
              title="App is active"
              action={{
                content: "Open Theme Editor",
                url: themeEditorUrl,
                external: true,
              }}
            >
              <Text as="p" variant="bodySm">
                {activeThemeName
                  ? `Running on ${activeThemeName}. `
                  : ""}
                Widget settings apply to your storefront instantly.
              </Text>
            </Banner>
          ) : (
            <Card>
              <BlockStack gap="400">
                <InlineStack align="space-between" blockAlign="center">
                  <InlineStack gap="200" blockAlign="center">
                    <Icon source={AlertCircleIcon} tone="warning" />
                    <Text as="h2" variant="headingMd">
                      Complete setup to go live
                    </Text>
                  </InlineStack>
                  <Button
                    variant="tertiary"
                    size="slim"
                    loading={revalidateState === "loading"}
                    onClick={revalidate}
                  >
                    Refresh
                  </Button>
                </InlineStack>

                {activeThemeName && (
                  <Text as="p" variant="bodySm" tone="subdued">
                    Theme: {activeThemeName}
                  </Text>
                )}

                <Divider />

                <InlineGrid columns={{ xs: 1, sm: 2 }} gap="400">
                  <Card>
                    <BlockStack gap="300">
                      <InlineStack gap="200" blockAlign="center">
                        <Badge tone="info">Step 1</Badge>
                        <Text as="h3" variant="headingSm">
                          Enable App Embed
                        </Text>
                      </InlineStack>
                      <Text as="p" variant="bodySm" tone="subdued">
                        Open Theme Editor, go to App Embeds, and toggle on Zip Code Checker.
                      </Text>
                      <Button
                        url={themeEditorAppEmbedsUrl}
                        target="_blank"
                        icon={ExternalIcon}
                      >
                        Open App Embeds
                      </Button>
                    </BlockStack>
                  </Card>

                  <Card>
                    <BlockStack gap="300">
                      <InlineStack gap="200" blockAlign="center">
                        <Badge>Step 2</Badge>
                        <Text as="h3" variant="headingSm">
                          Add Widget Block
                        </Text>
                      </InlineStack>
                      <Text as="p" variant="bodySm" tone="subdued">
                        Go to a Product template, add the Zip Code Checker block, and save.
                      </Text>
                      <Button
                        url={`${themeEditorUrl}?template=product`}
                        target="_blank"
                        icon={ExternalIcon}
                      >
                        Open Product Template
                      </Button>
                    </BlockStack>
                  </Card>
                </InlineGrid>

                <Text as="p" variant="bodySm" tone="subdued">
                  After completing both steps, click <strong>Refresh</strong> above.
                </Text>
              </BlockStack>
            </Card>
          )}

          {/* ─── 2. STATS ─── */}
          {!isEmpty && (
            <Card>
              <BlockStack gap="400">
                <InlineGrid columns={{ xs: 2, sm: 3, md: 5 }} gap="400">
                  <BlockStack gap="100">
                    <Text as="p" variant="headingXl" fontWeight="bold">
                      {stats.total}
                      {limits.maxZipCodes !== Infinity && (
                        <Text as="span" variant="bodySm" tone="subdued" fontWeight="regular">
                          {" "}/ {limits.maxZipCodes}
                        </Text>
                      )}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Total zip codes
                    </Text>
                  </BlockStack>

                  <BlockStack gap="100">
                    <Text as="p" variant="headingXl" fontWeight="bold" tone="success">
                      {stats.allowed}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Allowed
                    </Text>
                  </BlockStack>

                  <BlockStack gap="100">
                    <Text as="p" variant="headingXl" fontWeight="bold" tone={stats.blocked > 0 ? "critical" : "subdued"}>
                      {stats.blocked}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Blocked{isFreePlan ? " (Pro)" : ""}
                    </Text>
                  </BlockStack>

                  <BlockStack gap="100">
                    <Text as="p" variant="headingXl" fontWeight="bold" tone={stats.waitlist > 0 ? "caution" : "subdued"}>
                      {stats.waitlist}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      On waitlist
                    </Text>
                  </BlockStack>

                  <BlockStack gap="100">
                    <Text as="p" variant="headingXl" fontWeight="bold">
                      {stats.deliveryRules}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Delivery rules
                    </Text>
                  </BlockStack>
                </InlineGrid>

                {/* Usage bar — inline, only on free plan */}
                {isFreePlan && limits.maxZipCodes !== Infinity && (
                  <>
                    <Divider />
                    <BlockStack gap="200">
                      <InlineStack align="space-between">
                        <Text as="p" variant="bodySm" tone="subdued">
                          Plan usage
                        </Text>
                        <Text as="p" variant="bodySm" fontWeight="semibold" tone={usagePercent >= 80 ? "critical" : "subdued"}>
                          {usagePercent}%
                        </Text>
                      </InlineStack>
                      <ProgressBar
                        progress={usagePercent}
                        tone={usagePercent >= 80 ? "critical" : "highlight"}
                        size="small"
                      />
                    </BlockStack>
                  </>
                )}
              </BlockStack>
            </Card>
          )}

          {/* ─── 3. UPGRADE PROMPT ─── */}
          {isFreePlan && !isEmpty && usagePercent >= 60 && (
            <Banner
              tone="warning"
              action={{
                content: "Upgrade to Pro",
                onAction: () => navigate("/app/pricing"),
              }}
            >
              <Text as="p" variant="bodySm">
                You&apos;ve used {stats.total} of {limits.maxZipCodes} zip codes.
                Upgrade for unlimited zip codes, blocked zones, and delivery rules.
              </Text>
            </Banner>
          )}

          {/* ─── 4. GETTING STARTED ─── */}
          {isEmpty && (
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd">
                  Get started in 3 steps
                </Text>
                <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
                  {[
                    {
                      step: "1",
                      title: "Add your zip codes",
                      desc: "Add delivery areas one by one or import via CSV.",
                      action: "Add Zip Codes",
                      href: "/app/zip-codes",
                      primary: true,
                    },
                    {
                      step: "2",
                      title: "Customize widget",
                      desc: "Match the checker to your store's look and feel.",
                      action: "Customize",
                      href: "/app/widget",
                      primary: false,
                    },
                    {
                      step: "3",
                      title: "Set delivery rules",
                      desc: "Configure fees, cutoff times, and schedules.",
                      action: "Set Rules",
                      href: "/app/delivery-rules",
                      primary: false,
                    },
                  ].map((item) => (
                    <Box
                      key={item.step}
                      padding="400"
                      background="bg-surface-secondary"
                      borderRadius="300"
                    >
                      <BlockStack gap="200">
                        <InlineStack gap="200" blockAlign="center">
                          <Box
                            background="bg-fill-brand"
                            borderRadius="full"
                            padding="100"
                            minWidth="24px"
                            minHeight="24px"
                          >
                            <Text
                              as="span"
                              variant="bodySm"
                              fontWeight="bold"
                              alignment="center"
                              tone="text-inverse"
                            >
                              {item.step}
                            </Text>
                          </Box>
                          <Text as="h3" variant="headingSm">
                            {item.title}
                          </Text>
                        </InlineStack>
                        <Text as="p" variant="bodySm" tone="subdued">
                          {item.desc}
                        </Text>
                        <Button
                          variant={item.primary ? "primary" : undefined}
                          size="slim"
                          onClick={() => navigate(item.href)}
                        >
                          {item.action}
                        </Button>
                      </BlockStack>
                    </Box>
                  ))}
                </InlineGrid>
              </BlockStack>
            </Card>
          )}

          {/* ─── 5. NAVIGATION ─── */}
          <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
            {[
              {
                title: "Zip Codes",
                desc: "Add, edit, import, or export.",
                stat: stats.total > 0 ? `${stats.total} total` : undefined,
                href: "/app/zip-codes",
              },
              {
                title: "Delivery Rules",
                desc: "Fees, cutoff times, schedules.",
                stat: stats.deliveryRules > 0 ? `${stats.deliveryRules} rules` : undefined,
                href: "/app/delivery-rules",
              },
              {
                title: "Waitlist",
                desc: "Customers waiting for delivery.",
                stat: stats.waitlist > 0 ? `${stats.waitlist} waiting` : undefined,
                href: "/app/waitlist",
              },
              {
                title: "Widget",
                desc: "Customize look and feel.",
                href: "/app/widget",
              },
            ].map((item) => (
              <Card key={item.title}>
                <BlockStack gap="200">
                  <InlineStack align="space-between" blockAlign="center">
                    <Text as="h3" variant="headingSm">
                      {item.title}
                    </Text>
                    {item.stat && (
                      <Badge tone="info">{item.stat}</Badge>
                    )}
                  </InlineStack>
                  <Text as="p" variant="bodySm" tone="subdued">
                    {item.desc}
                  </Text>
                  <Button
                    size="slim"
                    onClick={() => navigate(item.href)}
                  >
                    Manage
                  </Button>
                </BlockStack>
              </Card>
            ))}
          </InlineGrid>

        </BlockStack>
      </Box>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

