            >
              <Text as="p" variant="bodySm">
                {activeThemeName
                  ? `Running on ${activeThemeName}. `
                  : ""}
                Widget settings apply to your storefront instantly.
              </Text>
            </Banner>
          ) : (
            <Card>
              <BlockStack gap="400">
                <InlineStack align="space-between" blockAlign="center">
                  <InlineStack gap="200" blockAlign="center">
                    <Icon source={AlertCircleIcon} tone="warning" />
                    <Text as="h2" variant="headingMd">
                      Complete setup to go live
                    </Text>
                  </InlineStack>
                  <Button
                    variant="tertiary"
                    size="slim"
                    loading={revalidateState === "loading"}
                    onClick={revalidate}
                  >
                    Refresh
                  </Button>
                </InlineStack>

                {activeThemeName && (
                  <Text as="p" variant="bodySm" tone="subdued">
                    Theme: {activeThemeName}
                  </Text>
                )}

                <Divider />

                <InlineGrid columns={{ xs: 1, sm: 2 }} gap="400">
                  <Card>
                    <BlockStack gap="300">
                      <InlineStack gap="200" blockAlign="center">
                        <Badge tone="info">Step 1</Badge>
                        <Text as="h3" variant="headingSm">
                          Enable App Embed
                        </Text>
                      </InlineStack>
                      <Text as="p" variant="bodySm" tone="subdued">
                        Open Theme Editor, go to App Embeds, and toggle on Zip Code Checker.
                      </Text>
                      <Button
                        url={themeEditorAppEmbedsUrl}
                        target="_blank"
                        icon={ExternalIcon}
                      >
                        Open App Embeds
                      </Button>
                    </BlockStack>
                  </Card>

                  <Card>
                    <BlockStack gap="300">
                      <InlineStack gap="200" blockAlign="center">
                        <Badge>Step 2</Badge>
                        <Text as="h3" variant="headingSm">
                          Add Widget Block
                        </Text>
                      </InlineStack>
                      <Text as="p" variant="bodySm" tone="subdued">
                        Go to a Product template, add the Zip Code Checker block, and save.
