                  </Card>
                </InlineGrid>

                <Text as="p" variant="bodySm" tone="subdued">
                  After completing both steps, click <strong>Refresh</strong> above.
                </Text>
              </BlockStack>
            </Card>
          )}

          {/* ─── 2. STATS ─── */}
          {!isEmpty && (
            <Card>
