        ? "Pro"
        : "Free";

  return (
    <Page
      title="Dashboard"
      subtitle={`${planLabel} Plan`}
      primaryAction={{
        content: "Add Zip Code",
        icon: PlusIcon,
        onAction: () => navigate("/app/zip-codes"),
      }}
    >
      <Box paddingBlockEnd="1600">
        <BlockStack gap="500">

          {/* ─── 1. APP STATUS ─── */}
          {appEmbedEnabled ? (
