                            padding="100"
                            minWidth="24px"
                            minHeight="24px"
                          >
                            <Text
                              as="span"
                              variant="bodySm"
                              fontWeight="bold"
                              alignment="center"
                              tone="text-inverse"
                            >
                              {item.step}
                            </Text>
                          </Box>
                          <Text as="h3" variant="headingSm">
                            {item.title}
                          </Text>
                        </InlineStack>
                        <Text as="p" variant="bodySm" tone="subdued">
                          {item.desc}
                        </Text>
                        <Button
                          variant={item.primary ? "primary" : undefined}
                          size="slim"
                          onClick={() => navigate(item.href)}
                        >
                          {item.action}
                        </Button>
                      </BlockStack>
                    </Box>
                  ))}
                </InlineGrid>
              </BlockStack>
            </Card>
          )}

          {/* ─── 5. NAVIGATION ─── */}
          <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
            {[
              {
                title: "Zip Codes",
                desc: "Add, edit, import, or export your service areas.",
                stat: stats.total > 0 ? `${stats.total} total` : undefined,
                action: "Manage zip codes",
                href: "/app/zip-codes",
              },
              {
                title: "Delivery Rules",
                desc: "Set fees, cutoff times, and schedules by zone.",
                stat: stats.deliveryRules > 0 ? `${stats.deliveryRules} rules` : undefined,
                action: "Manage rules",
                href: "/app/delivery-rules",
              },
              {
                title: "Waitlist",
                desc: "View customers requesting delivery to new areas.",
                stat: stats.waitlist > 0 ? `${stats.waitlist} waiting` : undefined,
                action: "View waitlist",
                href: "/app/waitlist",
              },
              {
                title: "Widget",
                desc: "Customize colors, text, and layout on your store.",
                action: "Customize widget",
                href: "/app/widget",
              },
            ].map((item) => (
              <Card key={item.title}>
                <BlockStack gap="200">
                  <InlineStack align="space-between" blockAlign="center">
                    <Text as="h3" variant="headingSm">
                      {item.title}
                    </Text>
                    {item.stat && (
                      <Badge tone="info">{item.stat}</Badge>
                    )}
                  </InlineStack>
                  <Text as="p" variant="bodySm" tone="subdued">
                    {item.desc}
                  </Text>
                  <Button
                    size="slim"
                    onClick={() => navigate(item.href)}
                  >
                    {item.action}
                  </Button>
                </BlockStack>
              </Card>
            ))}
          </InlineGrid>

        </BlockStack>
      </Box>
    </Page>
  );
}

