export const PLAN_ULTIMATE_ANNUAL = "Ultimate Annual";

export const ALL_PAID_PLANS = [
  PLAN_PRO_MONTHLY,
  PLAN_PRO_ANNUAL,
  PLAN_ULTIMATE_MONTHLY,
  PLAN_ULTIMATE_ANNUAL,
];

export const PLAN_LIMITS = {
  free: { maxZipCodes: 25, allowBlocked: false, label: "Free" },
  pro: { maxZipCodes: Infinity, allowBlocked: true, label: "Pro" },
  ultimate: { maxZipCodes: Infinity, allowBlocked: true, label: "Ultimate" },
};

export function getPlanTier(planName: string): "free" | "pro" | "ultimate" {
  if (planName === PLAN_PRO_MONTHLY || planName === PLAN_PRO_ANNUAL)
    return "pro";
  if (planName === PLAN_ULTIMATE_MONTHLY || planName === PLAN_ULTIMATE_ANNUAL)
    return "ultimate";
  return "free";
}

