                      {stats.allowed}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Serviceable
                    </Text>
                  </BlockStack>

                  <BlockStack gap="100">
                    <Text as="p" variant="headingXl" fontWeight="bold" tone={stats.blocked > 0 ? "critical" : "subdued"}>
                      {stats.blocked}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Blocked
                    </Text>
                  </BlockStack>

                  <BlockStack gap="100">
                    <Text as="p" variant="headingXl" fontWeight="bold" tone={stats.waitlist > 0 ? "caution" : "subdued"}>
                      {stats.waitlist}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Waitlisted
                    </Text>
                  </BlockStack>

                  <BlockStack gap="100">
                    <Text as="p" variant="headingXl" fontWeight="bold">
                      {stats.deliveryRules}
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Delivery rules
                    </Text>
                  </BlockStack>
                </InlineGrid>

                {/* Usage bar — shown when plan has a finite zip limit */}
                {hasZipLimit && (
                  <>
                    <Divider />
                    <BlockStack gap="200">
                      <InlineStack align="space-between">
                        <Text as="p" variant="bodySm" tone="subdued">
                          Plan usage
                        </Text>
                        <Text as="p" variant="bodySm" fontWeight="semibold" tone={usagePercent >= 80 ? "critical" : "subdued"}>
                          {usagePercent}%
                        </Text>
                      </InlineStack>
                      <ProgressBar
                        progress={usagePercent}
                        tone={usagePercent >= 80 ? "critical" : "highlight"}
                        size="small"
                      />
                    </BlockStack>
                  </>
                )}
              </BlockStack>
            </Card>
          )}

          {/* ─── 3. UPGRADE PROMPT ─── */}
          {isFreePlan && !isEmpty && usagePercent >= 60 && (
            <Banner
              tone="warning"
              action={{
                content: "Upgrade to Pro",
                onAction: () => navigate("/app/pricing"),
              }}
            >
              <Text as="p" variant="bodySm">
                You&apos;re using {stats.total} of {limits.maxZipCodes} zip codes on the Free plan.
                Upgrade to unlock unlimited zip codes, blocked zones, and delivery rules.
              </Text>
            </Banner>
          )}

          {/* ─── 4. GETTING STARTED ─── */}
          {isEmpty && (
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd">
